    modelAnswer: 'Uma função é injetora quando elementos diferentes do domínio sempre geram resultados diferentes (nunca dois valores de entrada distintos produzem a mesma saída). É sobrejetora quando todo elemento do contraditório (conjunto de chegada) é efetivamente atingido por algum elemento do domínio — não sobra nenhum valor "de fora". Uma função é bijetora quando é simultaneamente injetora e sobrejetora. A função inversa só existe (como função, no sentido pleno) quando a função original é bijetora: se ela não for injetora, ao tentar "desfazer" a função, um mesmo valor de saída corresponderia a mais de um valor de entrada possível, o que violaria a própria definição de função (cada entrada deve ter uma única saída correspondente); se não for sobrejetora, existiriam elementos no contradomínio para os quais a função inversa simplesmente não teria definição.',
