    modelAnswer: 'Dentro dos números reais, não existe nenhum número cujo quadrado seja negativo (todo número real elevado ao quadrado é sempre ≥ 0). Isso significa que equações do 2º grau com discriminante negativo, como x² + 4 = 0 (ou seja, x² = -4), não têm nenhuma solução dentro dos números reais. Para resolver esse tipo de equação, foi criada a unidade imaginária i, definida por i² = -1, permitindo escrever x = ±2i como solução (já que (2i)² = 4×i² = 4×(-1) = -4). Os números complexos, formados por uma parte real e uma parte imaginária (a + bi), estendem o sistema numérico exatamente para cobrir esses casos que ficavam sem solução nos números reais.',
