    prompt: 'Explique por que, em um polinômio com coeficientes reais, as raízes complexas (não reais) sempre aparecem em pares conjugados (a + bi e a - bi), e o que isso implica sobre o número de raízes reais de um polinômio de grau ímpar.',
    modelAnswer: 'Quando um polinômio tem coeficientes reais e uma raiz complexa a+bi é substituída na equação, o resultado envolve termos com i que precisam se cancelar para que a soma final seja zero (já que o polinômio, calculado nessa raiz, deve dar exatamente zero, um número real). Esse cancelamento só ocorre de forma consistente se o conjugado a-bi também for raiz do mesmo polinômio, "equilibrando" as partes imaginárias. Como consequência, raízes complexas não reais sempre aparecem em pares. Isso implica que, em um polinômio de grau ímpar (que tem um número ímpar de raízes ao todo, contando multiplicidade), como as raízes complexas só podem ocupar posições em pares (números pares), necessariamente sobra pelo menos uma raiz que não pode ser complexa — ou seja, todo polinômio de grau ímpar com coeficientes reais tem ao menos uma raiz real.',
