    modelAnswer: 'No plano de Argand-Gauss, um número complexo a+bi é representado como o ponto de coordenadas (a,b), onde o eixo horizontal representa a parte real e o eixo vertical representa a parte imaginária. O módulo de um número complexo, calculado como √(a²+b²), corresponde exatamente à distância desse ponto até a origem (0,0) do plano — é a aplicação direta do Teorema de Pitágoras, tratando a e b como os catetos de um triângulo retângulo cuja hipotenusa liga o ponto à origem. Assim, quanto maior o módulo de um número complexo, mais distante ele está da origem no plano complexo.',
