    modelAnswer: 'Balancear uma equação química significa ajustar os coeficientes estequiométricos de reagentes e produtos para que o número total de átomos de cada elemento seja o mesmo dos dois lados da equação. Isso é uma exigência direta da Lei de Conservação da Massa (Lei de Lavoisier), segundo a qual, em uma reação química, a massa total dos reagentes deve ser igual à massa total dos produtos — átomos não são criados nem destruídos, apenas rearranjados em novas substâncias. Se a equação não estiver balanceada, as proporções entre os coeficientes não refletem corretamente essa conservação, e qualquer cálculo estequiométrico feito a partir dela (como massa de produto formado a partir de uma dada massa de reagente) resultará em valores incorretos, pois estará baseado em uma proporção que viola a conservação de átomos.',
