    modelAnswer: 'A Regra de Markovnikov prevê que, na adição de um ácido do tipo HX (como HBr ou HCl) a um alceno assimétrico, o hidrogênio (H) se liga preferencialmente ao carbono da dupla ligação que já possui mais átomos de hidrogênio (o carbono menos substituído), enquanto o halogênio (X) se liga ao carbono mais substituído. Isso acontece porque o mecanismo dessa reação passa por um intermediário carbocátion: quando o H⁺ se adiciona primeiro a um dos carbonos da dupla, o carbocátion resultante se forma no outro carbono — e carbocátions mais substituídos (terciários, por exemplo) são mais estáveis que carbocátions menos substituídos (primários), porque grupos alquila ao redor do carbono positivo ajudam a estabilizar a carga através de efeito indutivo e hiperconjugação. Como a reação segue o caminho que passa pelo intermediário mais estável (e portanto mais fácil de se formar), o produto principal é aquele que resulta do carbocátion mais estável.',
