    modelAnswer: 'A concentração em g/L expressa a massa de soluto (em gramas) dissolvida em cada litro de solução, sem levar em conta a natureza química do soluto — é uma medida puramente mássica. Já a concentração em mol/L (molaridade) expressa a quantidade de matéria de soluto (em mols) dissolvida em cada litro de solução, levando em conta o número de partículas (moléculas ou íons) de soluto, não apenas sua massa. Para converter de g/L para mol/L, é preciso dividir a concentração em g/L pela massa molar do soluto (em g/mol): concentração em mol/L = concentração em g/L ÷ massa molar. Essa conversão é necessária porque substâncias diferentes têm massas molares diferentes, então a mesma concentração em g/L pode corresponder a quantidades de mols bem diferentes, dependendo do soluto.',
