    modelAnswer: 'Uma solução insaturada é aquela em que a quantidade de soluto dissolvido está abaixo do limite máximo que o solvente consegue dissolver naquela temperatura (o chamado coeficiente de solubilidade) — ainda seria possível dissolver mais soluto. Uma solução saturada é aquela em que a quantidade de soluto dissolvido atingiu exatamente esse limite máximo — qualquer soluto adicional não se dissolve e permanece como corpo de fundo (precipitado). Já uma solução supersaturada é um estado instável e incomum em que a solução contém mais soluto dissolvido do que o previsto pelo coeficiente de solubilidade naquela temperatura — geralmente obtida por resfriamento cuidadoso de uma solução saturada preparada a quente, e que tende a precipitar o excesso de soluto ao menor distúrbio. Essa distinção é importante porque a mesma concentração numérica (em g/L, por exemplo) pode representar situações físicas completamente diferentes dependendo de qual desses três estados a solução se encontra.',
