    modelAnswer: 'A Lei de Hess estabelece que a variação de entalpia de uma reação química depende apenas dos estados inicial (reagentes) e final (produtos), e não do caminho (número de etapas) percorrido entre eles — a entalpia é uma função de estado. Por isso, se uma reação global puder ser obtida somando-se (algebricamente) duas ou mais reações intermediárias, a variação de entalpia dessa reação global será exatamente igual à soma das variações de entalpia dessas reações intermediárias, desde que elas se cancelem e se somem corretamente para reproduzir a equação da reação global. Essa propriedade é extremamente útil na prática, porque permite calcular o ΔH de reações difíceis (ou impossíveis) de medir diretamente em laboratório, combinando dados de outras reações mais fáceis de medir experimentalmente.',
