    modelAnswer: 'A energia de ativação é a barreira de energia mínima que os reagentes precisam superar para que a reação ocorra, mesmo que o produto final tenha menos energia que os reagentes (no caso de uma reação exotérmica). No diagrama de energia de uma reação, os reagentes começam em um determinado nível de energia, sobem até um pico (o "estado de transição", correspondente à energia de ativação) e depois descem até o nível de energia dos produtos. O fato de uma reação ser exotérmica (ΔH negativo, produtos com menos energia que reagentes) diz respeito apenas à diferença entre os níveis inicial e final — não diz nada sobre a altura da barreira (energia de ativação) que precisa ser superada no meio do caminho. Por isso, é perfeitamente possível (e comum) que uma reação exotérmica tenha uma energia de ativação alta, o que explica, por exemplo, por que a queima da madeira (reação bastante exotérmica) não ocorre espontaneamente à temperatura ambiente, precisando de uma fonte externa de energia (como uma faísca) para vencer essa barreira inicial.',
