    modelAnswer: 'A glicólise é a primeira etapa tanto da respiração aeróbica quanto da fermentação, ocorrendo da mesma forma em ambos os casos: no citosol, sem necessidade de oxigênio, quebrando uma molécula de glicose em duas de ácido pirúvico (piruvato), com produção líquida de 2 ATP e 2 NADH. A diferença entre os dois processos está no que acontece depois da glicólise, com o piruvato: na respiração aeróbica (na presença de oxigênio), o piruvato entra na mitocôndria, é convertido em acetil-CoA e segue para o ciclo de Krebs e a cadeia respiratória, sendo oxidado completamente até CO2 e água, com produção de muito mais ATP. Na fermentação (na ausência de oxigênio), o piruvato permanece no citosol e é convertido em outro produto (ácido lático, na fermentação lática, ou etanol e CO2, na fermentação alcoólica), com o objetivo principal de regenerar o NAD+ consumido na glicólise, permitindo que ela continue.',
