    modelAnswer: 'Lamarck propôs que características adquiridas durante a vida de um indivíduo, por uso ou desuso de determinada estrutura (como o pescoço da girafa se alongando pelo esforço de esticar-se para alcançar folhas altas), poderiam ser transmitidas diretamente à prole. Essa ideia é hoje considerada incorreta, porque características adquiridas durante a vida (não codificadas originalmente no material genético) não são, em geral, transmitidas geneticamente aos descendentes. Já Darwin propôs que a variação já existe naturalmente na população (por causas que ele não conhecia detalhadamente, hoje entendidas como mutações e recombinação genética), e que o ambiente seleciona, entre essa variação já existente, os indivíduos mais aptos, que sobrevivem e se reproduzem mais — a característica vantajosa (como um pescoço mais longo) não surge por esforço individual, mas já estava presente, ao acaso, em alguns indivíduos da população antes mesmo da pressão ambiental atuar.',
