    modelAnswer: 'A escala de um mapa representa a relação entre uma distância medida no mapa e a distância real correspondente no terreno — por exemplo, uma escala 1:50.000 significa que 1 unidade no mapa equivale a 50.000 dessas mesmas unidades na realidade. O termo "escala grande" se refere ao valor da fração (1/1.000 é maior que 1/1.000.000), e não ao tamanho da área representada. Por isso, contra a intuição inicial, uma escala grande (fração maior, como 1:1.000) representa uma área menor do terreno, mas com muito mais riqueza de detalhes (como ruas individuais de um bairro), enquanto uma escala pequena (fração menor, como 1:1.000.000) representa uma área muito maior (como um país inteiro), mas necessariamente com muito menos detalhe, já que cada centímetro do mapa corresponde a uma distância real enorme.',
