    modelAnswer: 'A superfície da Terra é aproximadamente esférica (uma superfície tridimensional curva), enquanto um mapa é uma representação bidimensional e plana. Matematicamente, não é possível "achatar" uma superfície esférica em um plano sem esticar, comprimir ou cortar partes dela — é o mesmo problema de tentar achatar a casca de uma laranja sem rasgá-la ou deformá-la. Por isso, toda projeção cartográfica (o método de transferir a superfície esférica para o plano) necessariamente introduz algum tipo de distorção — seja nas áreas, nos ângulos/formas, ou nas distâncias. Como não existe uma projeção perfeita que preserve tudo simultaneamente, diferentes projeções foram desenvolvidas priorizando preservar propriedades diferentes conforme o uso pretendido: projeções conformes (como Mercator) priorizam ângulos e formas locais, úteis para navegação; projeções equivalentes (como Peters) priorizam áreas reais, úteis para comparar o tamanho de países.',
