    modelAnswer: 'Rios de planalto atravessam terrenos com desníveis acentuados, formando corredeiras, quedas d\'água e trechos de forte correnteza. Essa energia potencial da água caindo de níveis mais altos para mais baixos é justamente o que torna esses rios atrativos para a geração de energia hidrelétrica, já que usinas aproveitam essa diferença de altura (queda d\'água) para girar turbinas. Por outro lado, essa mesma correnteza forte e os desníveis tornam a navegação difícil ou impossível em grandes trechos. Já rios de planície percorrem terrenos com pouca declividade, resultando em correnteza mais lenta e estável — condições mais favoráveis à navegação de embarcações, mas com menor potencial energético (por não haver desníveis significativos de altura para gerar energia hidrelétrica de forma eficiente).',
