    modelAnswer: 'Uma cadeia produtiva global é a fragmentação do processo de fabricação de um produto entre diferentes países, de modo que cada etapa da produção ocorre onde é mais vantajosa economicamente — seja por custo de mão de obra, disponibilidade de matéria-prima, infraestrutura logística ou nível tecnológico disponível. Por exemplo, em um produto eletrônico hipotético, o design e os componentes de alta tecnologia (como processadores) podem ser desenvolvidos em um país com forte tradição em pesquisa e desenvolvimento; certas matérias-primas ou componentes mais simples podem vir de países com esses recursos naturais ou com produção industrial mais barata; a montagem final, que costuma exigir grande quantidade de mão de obra, pode ocorrer em um terceiro país onde o custo do trabalho é mais baixo; e a distribuição e venda ocorrem globalmente, em mercados consumidores diversos. Esse processo é uma marca central da globalização econômica contemporânea, permitindo às empresas otimizar custos em escala mundial, mas também gerando debates sobre condições de trabalho e distribuição desigual do valor agregado entre os países envolvidos.',
    keyPoints: [
      'Cadeia produtiva global: cada etapa da produção de um produto ocorre no país mais vantajoso economicamente',
      'Fatores que determinam a localização de cada etapa: custo de mão de obra, matéria-prima, infraestrutura, tecnologia',
      'Exemplo coerente aplicado (design/componentes em um país, montagem em outro, distribuição global)',
    ],
    difficulty: 'medium',
