    modelAnswer: 'O Cerrado é uma savana tropical, com vegetação predominante de árvores baixas e tortuosas, arbustos e um extenso estrato herbáceo — visualmente menos exuberante que a floresta densa e alta da Amazônia. No entanto, essa aparência simples esconde uma biodiversidade excepcional: o Cerrado abriga uma enorme variedade de espécies vegetais e animais, muitas delas endêmicas (que não existem em nenhum outro lugar do mundo), adaptadas às condições específicas do bioma, como solos ácidos, estação seca prolongada e ocorrência natural de incêndios. Ao mesmo tempo, o Cerrado é um dos biomas brasileiros mais ameaçados justamente porque suas características (solo plano, relevo suave, clima com estação seca bem definida) o tornam altamente favorável à expansão da agricultura mecanizada (especialmente soja e pecuária), levando a taxas de desmatamento e conversão para uso agrícola historicamente muito altas — em muitos períodos, proporcionalmente maiores do que as observadas na Amazônia.',
