    modelAnswer: 'O desmatamento da Amazônia tem consequências que ultrapassam as fronteiras nacionais e regionais por diversos motivos interligados. A floresta amazônica funciona como um enorme reservatório de carbono, armazenado na biomassa das árvores; ao ser desmatada e, muitas vezes, queimada, essa floresta libera grandes quantidades de gás carbônico (CO2) na atmosfera, contribuindo para o efeito estufa intensificado e as mudanças climáticas globais — um fenômeno que afeta todo o planeta, não apenas o Brasil. Além disso, a Amazônia desempenha um papel importante na regulação do regime de chuvas em boa parte da América do Sul (por meio da evapotranspiração da floresta, que ajuda a formar as chamadas "rios voadores" de umidade), de modo que seu desmatamento pode alterar padrões climáticos regionais para além do próprio território amazônico. Por fim, a Amazônia abriga uma biodiversidade imensa e ainda não totalmente catalogada pela ciência, cuja perda representa uma redução irreversível da diversidade biológica do planeta como um todo.',
