    modelAnswer: 'A concentração industrial no Sudeste resulta da combinação de vários fatores históricos que se reforçaram mutuamente. Primeiro, o capital acumulado pela cafeicultura (atividade econômica muito lucrativa concentrada principalmente em São Paulo e no Rio de Janeiro nos séculos XIX e XX) forneceu recursos financeiros que puderam ser reinvestidos na instalação de indústrias. Segundo, a região atraiu grande contingente de mão de obra, inclusive imigrantes europeus que vieram originalmente para trabalhar nas lavouras de café e depois migraram para o trabalho industrial urbano. Terceiro, a infraestrutura de transporte (estradas de ferro construídas originalmente para escoar a produção cafeeira) já conectava a região, facilitando a distribuição de matérias-primas e produtos industrializados. Por fim, a proximidade com um grande e crescente mercado consumidor urbano na própria região reforçou a vantagem de instalar fábricas ali, em vez de em regiões distantes dos principais centros consumidores — mesmo que essas outras regiões tivessem recursos naturais relevantes, faltavam a elas o capital acumulado, a mão de obra disponível e a infraestrutura já existente que o Sudeste oferecia.',
