    modelAnswer: 'Uma economia fortemente baseada em commodities é aquela cuja pauta de exportações é dominada por produtos primários padronizados (agrícolas, como soja e café, ou minerais, como minério de ferro), negociados em larga escala em mercados internacionais, com preços definidos globalmente pela oferta e demanda mundial, e com pouca diferenciação ou agregação de valor entre os produtores de diferentes países. Essa é uma característica marcante da economia brasileira, que é um dos maiores exportadores mundiais de diversas commodities agrícolas e minerais. Um risco econômico importante associado a essa dependência é a vulnerabilidade às flutuações de preços internacionais dessas commodities: como os preços são definidos externamente pelo mercado global (e não pelo próprio país exportador), uma queda brusca no preço internacional de uma commodity importante pode impactar significativamente a balança comercial, a arrecadação e a economia como um todo — uma vulnerabilidade menor em economias mais diversificadas, com maior participação de produtos manufaturados de maior valor agregado na pauta exportadora.',
