    modelAnswer: 'A partir das últimas décadas do século XX, observou-se no Brasil um processo de desconcentração industrial, no qual empresas passaram a se instalar cada vez mais em regiões fora do Sudeste, que historicamente concentrava a maior parte da indústria nacional. Esse movimento foi impulsionado por diversos fatores: a chamada "guerra fiscal" entre estados, em que governos estaduais de outras regiões passaram a oferecer incentivos fiscais significativos (redução ou isenção de impostos) para atrair novas indústrias; os custos de mão de obra e de terrenos mais baixos em regiões fora do Sudeste, já saturado e com custos mais altos; a melhoria gradual da infraestrutura de transporte e energia em outras regiões, tornando-as logisticamente mais viáveis; e a busca por proximidade de novos mercados consumidores em expansão fora do eixo Sudeste. Esse processo não significou o desaparecimento da indústria no Sudeste (que ainda concentra parcela expressiva da produção industrial nacional), mas uma redistribuição relativa da atividade industrial pelo território, com crescimento proporcionalmente maior em outras regiões.',
