    modelAnswer: 'A democracia ateniense permitia que os cidadãos participassem diretamente das decisões políticas, deliberando e votando pessoalmente na Ecclesia (assembleia), sem a mediação de representantes eleitos — daí o nome "democracia direta". No entanto, a categoria de "cidadão" em Atenas era extremamente restrita: apenas homens livres, nascidos em Atenas de pai ateniense, eram considerados cidadãos com direito à participação política. Isso excluía automaticamente as mulheres (que não tinham direitos políticos), as pessoas escravizadas (uma parcela muito grande da população, essencial para sustentar a economia) e os estrangeiros residentes (metecos), mesmo que vivessem e trabalhassem em Atenas há muito tempo. Por isso, embora o princípio da participação direta seja admirado até hoje, a base de quem podia efetivamente participar era muito mais restrita do que a ideia moderna de democracia, baseada (ao menos formalmente) em cidadania universal.',
