    modelAnswer: 'Administrar um império que se estendia por três continentes, com povos, línguas e culturas muito diversas, exigia mecanismos de integração e controle eficazes. O Direito Romano forneceu um sistema jurídico relativamente uniforme e sofisticado, que regulava desde questões comerciais até direitos de propriedade, dando previsibilidade e uma base comum de regras em diferentes partes do império — o que facilitava tanto a administração quanto o comércio entre regiões distantes. Já as obras de engenharia, como a extensa rede de estradas romanas e os aquedutos, resolveram problemas práticos essenciais para a manutenção do império: as estradas permitiam o deslocamento rápido de tropas (fundamental para defesa e controle militar) e de mercadorias (fundamental para o comércio e o abastecimento), enquanto os aquedutos garantiam abastecimento de água para as cidades, mesmo as mais distantes de Roma, sustentando a vida urbana em todo o território. Juntas, essas ferramentas jurídicas e de infraestrutura permitiram que Roma integrasse e administrasse, por séculos, um império de proporções sem precedentes na época.',
