    modelAnswer: 'A periodização histórica (a divisão da história em "idades" ou períodos) é uma construção historiográfica, geralmente baseada em eventos considerados suficientemente marcantes para representar uma transformação profunda na organização política, social ou econômica de uma região. A queda do Império Romano do Ocidente em 476 d.C. é usada como esse marco porque representou o colapso de uma estrutura política centralizada e vasta que havia integrado grande parte da Europa, do Norte da África e do Oriente Médio por séculos. Após esse colapso, o território que havia sido o Império Romano do Ocidente se fragmentou em diversos reinos menores, muitas vezes governados por povos germânicos que haviam invadido o território — dando início a um novo período (a Idade Média), caracterizado por essa fragmentação política e por transformações sociais e econômicas profundas (como o desenvolvimento do sistema feudal), bem diferentes da organização centralizada do período romano anterior.',
