    modelAnswer: 'No sistema feudal, a relação de vassalagem era um vínculo pessoal e hierárquico estabelecido entre dois nobres: um suserano (geralmente de posição social mais elevada, como um rei ou grande senhor) e um vassalo (de posição subordinada), formalizado por um juramento de fidelidade. Em troca dessa fidelidade e de serviços prestados pelo vassalo (principalmente militares, como fornecer soldados em caso de guerra), o suserano concedia ao vassalo um feudo — geralmente uma porção de terra, com os camponeses que nela trabalhavam — que o vassalo administrava e da qual retirava seu sustento e poder econômico local. Essa relação era recíproca: o vassalo devia lealdade, auxílio militar e conselho ao suserano; o suserano devia proteção e a concessão (e manutenção) do feudo ao vassalo. Essas relações pessoais, multiplicadas em cadeias (um vassalo podia ser, ele mesmo, suserano de outros vassalos menores), formavam a complexa hierarquia social e política característica da Europa feudal.',
