    modelAnswer: 'Durante boa parte da Idade Média, a economia feudal era predominantemente rural e baseada na posse de terra, com pouca circulação de moeda e comércio de longa distância limitado. A partir de determinado momento (sobretudo a Baixa Idade Média), o comércio começou a se intensificar, e cidades (burgos) que haviam ficado estagnadas ou pouco importantes voltaram a crescer como centros de troca comercial e produção artesanal. Nesse contexto, surgiu um novo grupo social, a burguesia — formada por comerciantes e artesãos urbanos, cuja riqueza vinha da atividade comercial e manufatureira, não da posse de terras. Isso representou uma transformação significativa porque introduziu uma nova fonte de poder econômico (o capital comercial) que não dependia da estrutura feudal tradicional (terra e relações de vassalagem), criando as bases para uma economia monetária crescente e para tensões sociais entre essa nova classe urbana em ascensão e a nobreza feudal tradicional — um processo que, ao longo dos séculos seguintes, contribuiria para transformações econômicas e políticas ainda mais profundas na Europa.',
