      'Pensadores como Montesquieu, Voltaire e Rousseau forneceram argumentos contra essas estruturas de poder',
      'Essas ideias influenciaram diretamente os objetivos da Revolução Francesa (fim do Absolutismo e dos privilégios, soberania popular)',
