    modelAnswer: 'A economia brasileira na Primeira República dependia fortemente da exportação de café, cujos preços eram definidos pelo mercado internacional. A Grande Depressão de 1929, uma crise econômica mundial originada nos Estados Unidos, provocou uma queda abrupta na demanda e nos preços internacionais de diversos produtos, incluindo o café — afetando gravemente a economia brasileira e, especificamente, o poder econômico da oligarquia cafeeira paulista, que havia sido a base de sustentação da política do "café com leite". Nesse contexto de fragilização econômica, ocorreu também uma ruptura política: ao contrário do que era esperado pelo acordo de revezamento, São Paulo tentou emplacar novamente um presidente de sua própria oligarquia, e Minas Gerais, rompendo o arranjo tradicional, apoiou a candidatura de Getúlio Vargas (do Rio Grande do Sul) em aliança com outros estados descontentes. A combinação dessa crise econômica profunda com a ruptura política da aliança "café com leite" criou as condições que levaram ao movimento armado de 1930, que depôs o presidente eleito e levou Vargas ao poder.',
