    modelAnswer: 'Nas décadas anteriores a 1994, o Brasil enfrentou um problema crônico e severo de inflação, chegando a episódios de hiperinflação em determinados momentos — o que corroía continuamente o poder de compra da população e gerava enorme instabilidade econômica, dificultando planejamento financeiro tanto para famílias quanto para empresas. Diversos planos econômicos anteriores haviam tentado, sem sucesso duradouro, controlar essa inflação. O Plano Real, implementado em 1994, adotou uma estratégia diferente, que incluiu um período de transição com uma unidade de referência de valor (a URV) para "ancorar" gradualmente as expectativas de preços da população antes da introdução efetiva da nova moeda (o Real), além de políticas fiscais e monetárias voltadas ao controle da emissão monetária. Essa estratégia foi bem-sucedida em romper o ciclo de hiperinflação de forma duradoura, tornando o Plano Real um marco histórico por ter conseguido, finalmente, estabilizar a economia brasileira após décadas de tentativas fracassadas, permitindo maior previsibilidade econômica para a população e para o país como um todo.',
