    topicId: 'por_sintaxe',
    subject: 'Português',
    prompt: 'Explique a diferença entre objeto direto e objeto indireto, relacionando isso à transitividade do verbo (transitivo direto x transitivo indireto).',
    modelAnswer: 'O objeto é o termo que completa o sentido de um verbo transitivo (um verbo cujo sentido, sozinho, fica incompleto). A diferença entre objeto direto e objeto indireto está relacionada a como o verbo se liga a esse complemento. Um verbo transitivo direto se liga ao seu complemento sem necessidade de uma preposição obrigatória — por exemplo, em "estudei a matéria", o verbo "estudar" liga-se diretamente a "a matéria" (pergunta-se "estudei o quê?"), sem preposição exigida, e por isso "a matéria" é objeto direto. Já um verbo transitivo indireto exige uma preposição específica para se ligar ao complemento — por exemplo, em "gosto de música", o verbo "gostar" exige a preposição "de" para se ligar a seu complemento ("gosto de quê?"), e por isso "de música" é objeto indireto. Reconhecer a transitividade do verbo (se ele exige ou não uma preposição obrigatória) é o critério central para identificar corretamente se o complemento é objeto direto ou indireto.',
    keyPoints: [
      'Objeto direto: completa verbo transitivo direto, sem preposição obrigatória',
      'Objeto indireto: completa verbo transitivo indireto, com preposição exigida pelo verbo',
      'Critério central: a transitividade do próprio verbo determina se o complemento será direto ou indireto',
    ],
    difficulty: 'medium',
