    prompt: 'Explique a diferença entre uma oração subordinada adjetiva e uma oração subordinada substantiva, dando um exemplo de cada.',
    modelAnswer: 'As orações subordinadas dependem sintaticamente de uma oração principal para completar seu sentido, e se classificam de acordo com a função que exercem em relação a essa oração principal. Uma oração subordinada adjetiva funciona como um adjetivo, qualificando ou restringindo o sentido de um substantivo (ou pronome) já mencionado na oração principal — por exemplo, em "o livro que comprei ontem é excelente", a oração "que comprei ontem" qualifica/especifica "o livro", funcionando como um adjetivo desse substantivo. Já uma oração subordinada substantiva funciona como um substantivo, exercendo funções como sujeito, objeto direto ou complemento nominal da oração principal — por exemplo, em "é necessário que os candidatos cheguem cedo", a oração "que os candidatos cheguem cedo" funciona como o próprio sujeito da oração principal ("é necessário" o quê? "que cheguem cedo"), comportando-se como um substantivo equivaleria a dizer "isso é necessário".',
