    topicId: 'por_sintaxe',
    subject: 'Português',
    prompt: 'Explique a função sintática do aposto, e por que ele se diferencia do predicativo, mesmo que ambos possam, à primeira vista, parecer estar "explicando" ou "qualificando" outro termo da oração.',
    modelAnswer: 'O aposto é um termo que serve para explicar, identificar, esclarecer ou detalhar outro termo da oração (geralmente um substantivo), sem depender de um verbo de ligação para isso — por exemplo, em "Maria, minha melhor amiga, chegou atrasada", o aposto "minha melhor amiga" está apenas identificando quem é Maria, funcionando de forma independente do verbo da oração ("chegou"), geralmente isolado por vírgulas. Já o predicativo é um termo que atribui uma característica ao sujeito (ou ao objeto), mas por meio de um verbo — no caso do predicativo do sujeito, tipicamente um verbo de ligação (como "ser", "estar", "parecer"), como em "Maria está cansada", onde "cansada" é o predicativo do sujeito, atribuindo uma característica a "Maria" através do verbo de ligação "está". A diferença central, portanto, é que o aposto explica/identifica de forma mais independente do verbo, enquanto o predicativo atribui uma característica através, especificamente, da estrutura verbal da oração.',
