    prompt: 'Explique por que reconhecer a ironia em um texto exige que o leitor vá além do sentido literal das palavras, e o que pode acontecer se essa ironia não for percebida.',
    modelAnswer: 'A ironia é uma figura de linguagem em que o autor comunica, propositalmente, um sentido diferente (muitas vezes o oposto) do que as palavras literalmente expressam — por exemplo, dizer "que ótimo!" diante de uma situação claramente ruim, com intenção sarcástica. Para reconhecer a ironia, o leitor precisa ir além do sentido literal das palavras e considerar o contexto, o tom, e pistas indiretas que sinalizam essa intenção comunicativa diferente do que está escrito. Se a ironia não for percebida, o leitor corre o risco de interpretar o texto de forma exatamente invertida em relação ao que o autor realmente pretendia comunicar — tomando como sincera uma afirmação que era, na verdade, uma crítica sarcástica, o que pode levar a uma compreensão completamente equivocada do posicionamento real do autor sobre o assunto tratado.',
