    id: 'disc_por_texto_3',
    chapter: 'Fatores de Textualidade',
    topicId: 'por_texto',
    subject: 'Português',
    prompt: 'Explique por que apresentar e refutar um contra-argumento é considerada uma estratégia argumentativa eficaz, e não um sinal de fraqueza na defesa de uma tese.',
    modelAnswer: 'Uma primeira impressão possível é que mencionar um ponto de vista contrário à própria tese poderia enfraquecer a argumentação, sugerindo dúvida ou insegurança do autor. No entanto, quando bem executada, essa estratégia tem o efeito oposto: ao apresentar explicitamente um contra-argumento razoável e, em seguida, refutá-lo de forma consistente (mostrando por que ele não se sustenta, ou por que a tese defendida ainda é mais forte), o autor demonstra que já considerou perspectivas diferentes da sua antes de chegar à sua conclusão — o que aumenta, e não diminui, a credibilidade do texto. Além disso, essa estratégia antecipa e neutraliza objeções que o próprio leitor poderia levantar espontaneamente ao ler o texto, tornando a argumentação mais robusta e menos vulnerável a críticas simples, já que essas críticas já foram abordadas e respondidas dentro do próprio texto.',
