    modelAnswer: 'Gregório de Matos, poeta baiano do período colonial, é considerado o principal representante do Barroco brasileiro porque sua obra reúne de forma exemplar as características centrais desse movimento literário. Sua poesia é dividida tradicionalmente em três vertentes temáticas: a poesia religiosa (que expressa o temor do pecado e a busca pela salvação, refletindo o lado espiritual do conflito barroco), a poesia satírica (que critica de forma ácida e por vezes cômica os costumes e as autoridades da sociedade colonial baiana, valendo-lhe o apelido de "Boca do Inferno") e a poesia lírica (que trata de temas amorosos, também com o jogo de opostos característico do Barroco). Essa diversidade temática, combinada ao virtuosismo formal (cultismo e conceptismo) presente em seus versos, faz de Gregório de Matos uma figura central para entender como o Barroco se manifestou especificamente no contexto da colônia brasileira.',
