    modelAnswer: 'O Romantismo, como movimento literário, tinha entre seus objetivos centrais a construção de uma identidade cultural e nacional própria, distinta da tradição colonial portuguesa. No Brasil, José de Alencar contribuiu para esse projeto por meio do indianismo, elevando o indígena a uma figura heroica, nobre e idealizada — presente, por exemplo, em Peri (de "O Guarani") e na própria Iracema, personagens que simbolizam as origens "puras" e nobres da nação brasileira. Essa idealização não pretendia retratar de forma realista a vida indígena (que era, na prática, marcada por violência, opressão e desigualdade na sociedade colonial e imperial), mas sim construir um mito fundador para a identidade nacional, associando o Brasil a uma origem heroica e distinta de Portugal — um projeto literário e ideológico coerente com o espírito nacionalista mais amplo do Romantismo.',
