    modelAnswer: 'Um narrador não confiável é aquele cuja versão dos fatos apresentada ao leitor pode estar distorcida, seja por interesse próprio, por limitação de perspectiva, ou por qualquer outro motivo que comprometa a objetividade do relato — mesmo que o narrador esteja em primeira pessoa e pareça, à primeira vista, estar apenas contando "o que aconteceu". Em "Dom Casmurro", Bentinho narra em primeira pessoa sua suspeita de que Capitu o teria traído com seu melhor amigo, mas o leitor tem acesso apenas à perspectiva dele, já enviesada pelo ciúme e pela obsessão do narrador, sem qualquer confirmação objetiva e independente de que a traição de fato ocorreu. Isso muda fundamentalmente a forma como o leitor deve interpretar a obra: em vez de aceitar passivamente a versão de Bentinho como a verdade dos fatos, o leitor precisa adotar uma postura crítica, questionando a confiabilidade do narrador e considerando a possibilidade de que os "fatos" apresentados sejam, na verdade, uma interpretação distorcida e parcial da realidade pelo próprio narrador.',
