    modelAnswer: 'A Semana de Arte Moderna de 1922, realizada em São Paulo, reuniu artistas, escritores e intelectuais que buscavam romper com estéticas literárias e artísticas consideradas ultrapassadas — como o Parnasianismo (com seu apego rígido a formas poéticas clássicas e rimas) e o academicismo em geral, que ainda dominavam boa parte da produção cultural brasileira até então. Essa ruptura buscava, entre outros objetivos, a liberdade formal (como o uso do verso livre, sem obrigatoriedade de métrica ou rima fixa), a valorização da linguagem coloquial brasileira (em vez de um português mais formal e distante da fala cotidiana) e a busca por uma identidade artística e cultural genuinamente nacional, capaz de expressar a realidade e as particularidades do Brasil, em vez de simplesmente imitar modelos europeus. Esse evento é considerado o marco inaugural do Modernismo brasileiro justamente por consolidar, de forma coletiva e pública, essas propostas de renovação estética e cultural.',
