    prompt: 'Explique a proposta do "Manifesto Antropófago" de Oswald de Andrade, e por que a metáfora da "antropofagia" (devorar) foi escolhida para representar essa proposta cultural.',
    modelAnswer: 'O "Manifesto Antropófago" (1928), de Oswald de Andrade, propunha uma forma específica de a cultura brasileira lidar com influências culturais externas (principalmente europeias) e internas (indígenas, africanas): em vez de simplesmente copiar ou rejeitar essas influências, a proposta era "devorá-las" criticamente, assimilando o que fosse útil ou interessante, e recombinando esses elementos de forma original para criar algo genuinamente brasileiro. A metáfora da antropofagia (o ato ritual de alguns povos indígenas de devorar o inimigo para incorporar suas qualidades e força) foi escolhida justamente porque expressa bem essa ideia: não se trata de imitar passivamente o "outro" (as culturas estrangeiras), nem de rejeitá-lo completamente, mas de "devorá-lo" simbolicamente, incorporando seletivamente seus elementos e transformando-os em algo novo, próprio e original — uma forma criativa e não subalterna de lidar com influências culturais externas.',
