    modelAnswer: 'Diferentemente de movimentos literários anteriores (como o Romantismo ou o Modernismo), que possuíam características estéticas e temáticas relativamente bem definidas e compartilhadas por seus principais autores, a literatura brasileira contemporânea (produzida aproximadamente desde a segunda metade do século XX até hoje) não segue um único estilo ou escola dominante. Isso ocorre porque o período contemporâneo é marcado por uma multiplicidade de vozes, temas e abordagens estéticas coexistindo simultaneamente: autores explorando introspecção psicológica, outros focados em experimentação linguística, outros ainda voltados a temas sociais urgentes (como desigualdade, questões raciais e de gênero) ou dando voz a grupos historicamente marginalizados na literatura (autores negros, autores de periferias urbanas, entre outros). Essa diversidade reflete tanto a maior abertura editorial e cultural do período quanto a própria complexidade e pluralidade da sociedade brasileira contemporânea, que já não comporta uma única narrativa ou estética representativa de todo o período.',
