    prompt: 'Explique o que caracteriza a chamada "literatura marginal" (ou periférica), e por que ela representa uma mudança de perspectiva em relação a como as periferias urbanas eram tradicionalmente retratadas na literatura.',
    modelAnswer: 'A literatura marginal (ou periférica) é um movimento literário contemporâneo caracterizado por autores que, muitas vezes vindos das próprias periferias urbanas, narram essas realidades a partir de uma perspectiva interna — de dentro da própria vivência, e não como observadores externos. Isso representa uma mudança significativa em relação a uma tradição literária anterior, na qual as periferias e a pobreza urbana eram frequentemente retratadas por autores de fora dessas realidades, muitas vezes com um olhar distante, exotizado ou reduzido a estereótipos. Ao dar protagonismo à voz de quem de fato vive essas realidades, a literatura marginal traz uma complexidade, autenticidade e diversidade de perspectivas que dificilmente seriam alcançadas por um retrato feito exclusivamente de fora — ampliando o espectro de vozes e experiências representadas na literatura brasileira contemporânea.',
