    modelAnswer: 'O cânone literário (o conjunto de obras e autores tradicionalmente considerados centrais e mais valorizados dentro de uma tradição literária) foi historicamente composto, em sua maioria, por autores de determinados grupos sociais, deixando outras vozes e perspectivas sub-representadas por muito tempo. O crescente reconhecimento de autoras e autores negros na literatura contemporânea (como Conceição Evaristo, entre outros) é importante não apenas como uma questão de representatividade numérica, mas porque essas vozes trazem experiências, temas e formas de narrar historicamente ausentes ou pouco exploradas no cânone tradicional — como vivências específicas ligadas à identidade racial, à ancestralidade e a experiências sociais particulares dessas comunidades. Incorporar essas vozes de forma efetiva ao cânone amplia genuinamente a diversidade de perspectivas e experiências representadas na literatura nacional, enriquecendo (e não apenas complementando superficialmente) a compreensão mais completa da própria sociedade brasileira através da literatura.',
