    prompt: 'Explique a diferença entre um texto dissertativo-expositivo e um texto dissertativo-argumentativo, e por que essa diferença é importante para quem está se preparando para uma prova de redação como a do ENEM.',
    modelAnswer: 'Um texto dissertativo-expositivo tem como objetivo principal apresentar, explicar ou expor informações sobre um tema de forma relativamente neutra e objetiva, sem necessariamente defender um ponto de vista específico sobre a questão — é o tipo de texto comum, por exemplo, em verbetes enciclopédicos ou artigos informativos. Já um texto dissertativo-argumentativo vai além da simples exposição: ele defende explicitamente um ponto de vista (uma tese) sobre o tema, buscando convencer o leitor por meio de argumentos organizados e consistentes, muitas vezes sustentados por repertório sociocultural. Essa diferença é fundamental para quem se prepara para provas como a do ENEM porque a modalidade exigida é especificamente a dissertativo-argumentativa: um texto que apenas descreva ou explique o tema, sem de fato defender e sustentar um posicionamento claro, não atenderá plenamente aos critérios de avaliação da prova, mesmo que seja bem escrito do ponto de vista gramatical.',
