    prompt: 'Explique por que a "fuga ao tema" é considerada um dos erros mais graves em uma redação, mesmo quando o texto produzido é bem escrito e gramaticalmente correto.',
    modelAnswer: 'A fuga ao tema ocorre quando o candidato desenvolve um texto sobre um assunto diferente do que foi efetivamente proposto pela banca, ainda que de alguma forma relacionado superficial ou tangencialmente a ele. Esse erro é considerado extremamente grave (podendo até zerar a redação em exames como o ENEM) porque o objetivo central de uma prova de redação é avaliar a capacidade do candidato de responder especificamente ao que foi solicitado — não apenas de escrever bem sobre qualquer assunto relacionado. Um texto que foge ao tema, mesmo que apresente excelente domínio da norma-padrão, argumentação bem estruturada e repertório sociocultural rico, não está de fato cumprindo a tarefa proposta: ele está, na prática, respondendo a uma pergunta diferente da que foi feita. Por isso, a qualidade técnica do texto não compensa esse desvio — a pertinência ao tema específico proposto é um requisito básico e eliminatório, anterior a qualquer avaliação da qualidade da escrita em si.',
