    topicId: 'por_red_fundamentos',
    subject: 'Português',
    prompt: 'Explique por que a tese de uma redação deve ser apresentada de forma clara já na introdução, e o que pode acontecer se ela ficar ambígua ou pouco definida ao longo do texto.',
    modelAnswer: 'A tese é o ponto de vista central que o candidato pretende defender sobre o tema proposto, e ela deve ser apresentada de forma clara já na introdução porque é ela que orienta toda a estrutura argumentativa do restante do texto: os argumentos do desenvolvimento devem sustentar especificamente essa tese, e a conclusão deve retomá-la de forma coerente. Se a tese ficar ambígua ou pouco definida — por exemplo, se o candidato apenas descrever o tema sem deixar claro qual posição está de fato defendendo — o restante do texto tende a ficar desorientado, com argumentos que não se conectam claramente a um ponto de vista específico, comprometendo tanto a coerência quanto a força argumentativa geral do texto. Além disso, uma tese pouco clara dificulta a avaliação do texto, já que o avaliador precisa identificar claramente qual posição o candidato está defendendo para julgar se os argumentos apresentados realmente a sustentam de forma consistente.',
