    prompt: 'Explique por que construir repertório sociocultural com antecedência (antes do dia da prova) é uma estratégia mais eficaz do que tentar improvisar referências durante a própria redação.',
    modelAnswer: 'Construir repertório sociocultural com antecedência significa se familiarizar previamente, por meio de leitura e estudo, com diferentes temas — históricos, científicos, filosóficos, artísticos, sociais — que podem ser relevantes para diversas propostas de redação. Isso é mais eficaz do que tentar improvisar referências apenas durante a prova porque, sob a pressão do tempo limitado e da tensão do momento de avaliação, é muito mais difícil recordar, selecionar e articular de forma pertinente uma referência de qualidade "na hora" do que quando o candidato já possui, previamente, um repertório amplo e já assimilado sobre diversos assuntos. Ter repertório construído com antecedência também permite que o candidato escolha, entre diferentes referências já conhecidas, aquela que melhor se encaixa especificamente ao tema sorteado no dia da prova, em vez de forçar uma conexão pouco natural com a única referência que conseguiu lembrar de improviso.',
