    modelAnswer: 'Um parágrafo de desenvolvimento bem estruturado geralmente segue uma lógica de três momentos articulados. Primeiro, apresenta-se o argumento (a ideia central daquele parágrafo, relacionada à tese geral do texto) — a afirmação que será sustentada. Em seguida, desenvolve-se esse argumento, explicando-o, justificando-o ou ilustrando-o por meio de um dado, exemplo, referência ou raciocínio lógico que aprofunde e sustente a afirmação inicial, evitando que ela fique como uma simples opinião solta e não fundamentada. Por fim, é importante articular esse argumento de volta à tese central do texto, deixando claro como aquele ponto específico contribui para sustentar o posicionamento geral defendido pelo candidato. Essa estrutura evita tanto o problema de um parágrafo que apresenta apenas afirmações soltas sem sustentação quanto o problema de um parágrafo que se desenvolve, mas perde a conexão com a tese principal do texto.',
