    prompt: 'Explique o que caracteriza o erro argumentativo da "circularidade", e por que ele compromete a progressão de um texto dissertativo-argumentativo.',
    modelAnswer: 'A circularidade argumentativa ocorre quando um texto parece estar avançando (apresentando novas frases, novos parágrafos), mas, na prática, continua apenas reafirmando a mesma ideia inicial com palavras diferentes, sem de fato acrescentar novos ângulos, evidências, exemplos ou aprofundamento ao raciocínio já apresentado. Esse erro compromete a progressão textual — a expectativa de que um texto argumentativo avance, desenvolvendo e enriquecendo cada vez mais a discussão sobre o tema, com diferentes argumentos que se complementam, cada um trazendo algo novo à análise. Um texto circular, mesmo sendo tecnicamente coeso (bem conectado gramaticalmente) e usando vocabulário variado, na prática fica "parado" no mesmo ponto do raciocínio, dando a falsa impressão de desenvolvimento sem realmente aprofundar a discussão — um problema que pode ser percebido pelo avaliador mesmo que a redação use uma linguagem elaborada e pareça, superficialmente, bem escrita.',
