    modelAnswer: 'Os conectivos (como "portanto", "além disso", "no entanto", "por isso") são elementos linguísticos que explicitam a relação lógica entre diferentes partes de um texto — sinalizando ao leitor se a ideia seguinte é uma conclusão, uma adição, um contraste, uma causa, entre outras relações possíveis. Eles são fundamentais para a coesão porque tornam essas relações explícitas e claras, evitando que o leitor precise adivinhar como as ideias do texto se conectam entre si. Quando um conectivo é usado de forma inadequada — por exemplo, utilizando "no entanto" (que sinaliza contraste) para ligar duas ideias que, na verdade, se complementam ou se seguem logicamente (uma relação de adição ou conclusão) — o texto pode se tornar confuso ou até logicamente incorreto, sugerindo ao leitor uma relação entre as ideias que não corresponde à intenção real do autor, prejudicando a clareza e, possivelmente, a própria coerência do raciocínio apresentado.',
