    modelAnswer: 'Ao discutir problemas sociais complexos — como desigualdade, violência urbana ou vulnerabilidade social — uma proposta de intervenção que atribui a responsabilidade exclusivamente a escolhas ou características individuais das pessoas afetadas (ignorando fatores sociais, econômicos e históricos mais amplos) costuma ser considerada uma análise simplista. Isso ocorre porque problemas sociais complexos raramente têm uma única causa isolada no comportamento individual: eles geralmente resultam de uma combinação de fatores estruturais, como desigualdade histórica de acesso a educação, saúde e oportunidades econômicas, políticas públicas insuficientes, e contextos sociais específicos que limitam as escolhas disponíveis para os indivíduos afetados. Uma redação que consegue articular esses fatores estruturais à discussão demonstra uma compreensão mais madura e completa do problema, evitando o risco de culpabilizar injustamente indivíduos por circunstâncias que, em grande medida, escapam ao seu controle pessoal.',
