    prompt: 'Explique o princípio básico por trás da técnica de PCR (Reação em Cadeia da Polimerase), e por que ela permite amplificar um trecho específico de DNA a partir de uma quantidade muito pequena de amostra inicial.',
    modelAnswer: 'A PCR se baseia em ciclos repetidos de aquecimento e resfriamento de uma amostra de DNA, junto com uma enzima DNA polimerase resistente a calor, nucleotídeos livres, e pequenas sequências chamadas primers, que se ligam especificamente às extremidades do trecho de DNA que se deseja amplificar. Em cada ciclo: primeiro, o aquecimento separa as duas fitas do DNA (desnaturação); depois, o resfriamento permite que os primers se liguem especificamente às fitas separadas, marcando o início e o fim do trecho de interesse; por fim, a DNA polimerase sintetiza uma nova fita complementar a partir de cada primer, duplicando o trecho de DNA delimitado por eles. Como cada ciclo duplica a quantidade do trecho de DNA de interesse, repetir esse processo por dezenas de ciclos gera um crescimento exponencial (2ⁿ cópias após n ciclos) — permitindo obter milhões de cópias de um trecho específico de DNA a partir de uma quantidade inicial mínima de amostra.',
