    prompt: 'Explique como a tecnologia CRISPR-Cas9 permite editar precisamente um local específico do genoma, destacando o papel do RNA-guia.',
    modelAnswer: 'A tecnologia CRISPR-Cas9 usa uma molécula de RNA-guia, desenhada especificamente para ser complementar a uma sequência-alvo particular do DNA que se deseja editar. Esse RNA-guia se associa à enzima Cas9 e a direciona até o local exato do genoma correspondente à sua sequência complementar — funcionando como um "endereço" que leva a enzima até o alvo certo, entre bilhões de outras sequências de DNA no genoma. Uma vez no local correto, a enzima Cas9 realiza um corte preciso nas duas fitas do DNA naquele ponto específico. A célula então tenta reparar esse corte por seus próprios mecanismos naturais, e é justamente durante esse reparo que cientistas podem induzir alterações desejadas — como desativar um gene (se o reparo introduzir pequenos erros no processo) ou inserir uma nova sequência de DNA fornecida propositalmente junto com o sistema CRISPR.',
