    modelAnswer: 'A teoria da tensão-coesão-adesão explica a subida da seiva bruta pelo xilema sem depender de uma bomba ativa, usando três propriedades físicas da água. A transpiração (evaporação de água pelos estômatos das folhas) gera uma tensão (pressão negativa) no topo da coluna de água dentro do xilema. Essa tensão se propaga por toda a coluna de água graças à coesão — a atração entre as próprias moléculas de água (por pontes de hidrogênio), que as mantém unidas como uma coluna contínua, capaz de ser "puxada" de cima sem se romper. Além disso, a adesão — a atração entre as moléculas de água e as paredes dos vasos do xilema — ajuda a manter essa coluna aderida às paredes dos vasos, evitando que ela se separe deles. A combinação dessas três forças permite que a água suba passivamente, "puxada" pela transpiração no topo, sem que a planta precise de nenhum mecanismo de bombeamento ativo.',
