    modelAnswer: 'Os estômatos são poros na epiderme das folhas, delimitados por um par de células-guarda, que servem como a principal via de entrada de CO2 do ar (necessário para a fotossíntese) e, ao mesmo tempo, a principal via de perda de água por transpiração. Essas duas funções são opostas: manter os estômatos abertos favorece a entrada de CO2, mas também aumenta a perda de água; fechá-los evita a perda de água, mas também bloqueia a entrada de CO2, limitando a fotossíntese. As células-guarda regulam essa troca continuamente, ajustando sua turgescência (quantidade de água interna) de acordo com as condições ambientais: em condições de bastante água disponível e boa luminosidade, os estômatos tendem a ficar mais abertos, priorizando a fotossíntese; em condições de escassez de água (estresse hídrico), os estômatos se fecham parcial ou totalmente, priorizando a economia de água, mesmo que isso reduza temporariamente a fotossíntese.',
